CREATE OR REPLACE PROCEDURE augmenter_prix (p_categorie IN NUMBER, p_taux IN NUMBER) IS
BEGIN
  UPDATE produits SET prix = prix * (1 + p_taux / 100) WHERE categorie_id = p_categorie;
  IF SQL%ROWCOUNT = 0 THEN
    RAISE_APPLICATION_ERROR(-20010, 'Aucun produit dans cette catégorie');
  END IF;
END augmenter_prix;
/

